<?php
declare(strict_types=1);
namespace Plati;
if(!defined('PLATI_ENTRY')&&PHP_SAPI!=='cli'){http_response_code(404);exit;}

final class Problem extends \RuntimeException { public function __construct(string $message,public int $status=400){parent::__construct($message);} }
function json(mixed $value):string{return json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR);}
function canonical(array $row):string{ksort($row);return json($row);}
function hashSource(array $row):string{return hash('sha256',canonical($row));}
function storage():string{static $path;if($path!==null)return $path;$override=getenv('PLATI_DATA_DIR');$pointer=__DIR__.'/../storage.php';$path=$override!==false&&$override!==''?$override:(is_file($pointer)?require $pointer:__DIR__.'/../private');if(!is_string($path)||$path==='')throw new Problem('Director privat invalid.',503);return rtrim($path,'/\\');}
function configured():bool{return is_file(storage().'/config.php');}
function config():array{static $c;if(!configured())throw new Problem('Aplicația trebuie instalată prin setup.php.',503);return $c??=require storage().'/config.php';}
function preview():bool{return !configured()||config()['environment']==='rebuild-preview';}
function https():bool{return !empty($_SERVER['HTTPS'])&&strtolower((string)$_SERVER['HTTPS'])!=='off';}
function validConfiguration(array $c):bool{$environment=$c['environment']??'';if($environment==='rebuild-preview')return preg_match('/^pg_rebuild_[a-f0-9]{8}$/D',$c['database']??'')===1;if(in_array($environment,['staging','production'],true))return preg_match('/^pg_plati_[a-f0-9]{8}$/D',$c['database']??'')===1;return false;}

function db():\PDO{static $db;if($db)return $db;$c=config();if(!validConfiguration($c))throw new Problem('Configurare invalidă: se acceptă numai o bază nouă dedicată aplicației.',503);return $db=new \PDO('mysql:host='.$c['host'].';port='.$c['port'].';dbname='.$c['database'].';charset=utf8mb4',$c['user'],$c['password'],[\PDO::ATTR_ERRMODE=>\PDO::ERRMODE_EXCEPTION,\PDO::ATTR_DEFAULT_FETCH_MODE=>\PDO::FETCH_ASSOC,\PDO::ATTR_EMULATE_PREPARES=>false]);}
function query(\PDO $db,string $sql,array $args=[]):\PDOStatement{$q=$db->prepare($sql);$q->execute($args);return $q;}
function one(\PDO $db,string $sql,array $args=[]):?array{return query($db,$sql,$args)->fetch()?:null;}
function transaction(\PDO $db,callable $fn):mixed{if($db->inTransaction())return $fn();$db->beginTransaction();try{$r=$fn();$db->commit();return $r;}catch(\Throwable $e){if($db->inTransaction())$db->rollBack();if($e instanceof \PDOException&&in_array((int)($e->errorInfo[1]??0),[1062,1205,1213],true))throw new Problem('Datele au fost modificate simultan. Reîncarcă și verifică legătura existentă.',409);throw $e;}}
function audit(\PDO $db,string $type,array $details,?array $actor=null,?int $decision=null):void{query($db,'INSERT INTO audit_events(event_type,actor_id,decision_id,details_json,created_at) VALUES(?,?,?,?,UTC_TIMESTAMP())',[$type,$actor['id']??null,$decision,json($details)]);}
function user(\PDO $db):array{$u=isset($_SESSION['user'])?one($db,'SELECT id,username,display_name,role,enabled FROM users WHERE id=?',[$_SESSION['user']]):null;if(!$u||!$u['enabled'])throw new Problem('Autentifică-te pentru a continua.',401);return $u;}
function permit(array $user,string $permission):void{if($permission==='read')return;if($user['role']==='admin')return;if($permission==='operate'&&$user['role']==='operator')return;throw new Problem('Contul nu are permisiunea necesară.',403);}
function csrf():void{if(!hash_equals($_SESSION['csrf']??'',$_SERVER['HTTP_X_CSRF_TOKEN']??$_POST['csrf']??''))throw new Problem('Sesiune invalidă. Reîncarcă pagina.',403);}
function nameKey(string $name):string{$s=mb_strtolower(strtr($name,['Ă'=>'a','Â'=>'a','Î'=>'i','Ș'=>'s','Ş'=>'s','Ț'=>'t','Ţ'=>'t','ă'=>'a','â'=>'a','î'=>'i','ș'=>'s','ş'=>'s','ț'=>'t','ţ'=>'t']),'UTF-8');$s=preg_replace('/^\s*persoana\s+fizica\b[\s:–—-]*/u','',$s);$s=preg_replace('/\bs\s*\.\s*r\s*\.\s*l\s*\.?/u','srl',$s);$tokens=preg_split('/[^\p{L}\p{N}]+/u',trim($s),-1,PREG_SPLIT_NO_EMPTY);if(in_array('srl',$tokens,true)&&($tokens[0]??'')==='sc')array_shift($tokens);sort($tokens,SORT_STRING);return implode(' ',$tokens);}
function label(string $s):string{return mb_strtoupper(preg_replace('/\s+/u',' ',trim($s)),'UTF-8');}
function reference(string $s):array{preg_match_all('/\bGPD\s+([0-9]{1,30})\b/iu',$s,$m);$n=array_values(array_unique($m[1]));if($n)return ['kind'=>count($n)===1?'invoice':'ambiguous','id'=>count($n)===1?'GPD '.$n[0]:null];$ok=preg_match('/^(?:ID\s*(?:COMANDA\s*)?[:#-]?\s*)?([0-9]{1,30})$/i',trim($s),$m);return ['kind'=>$ok?'order':'none','id'=>$ok?$m[1]:null];}
function validDate(?string $date):bool{if(!$date||!preg_match('/^\d{4}-\d{2}-\d{2}$/D',$date))return false;[$y,$m,$d]=array_map('intval',explode('-',$date));return checkdate($m,$d,$y);}
function gap(string $a,string $b):int{return (int)(new \DateTimeImmutable($a))->diff(new \DateTimeImmutable($b))->format('%a');}
function method(array $s):?string{$service=['TRANSPORT MARFA'=>'STANDARD','TRANSPORT MARFA-CONT COLECTOR'=>'CONT COLECTOR'][label($s['service_raw']??'')]??label($s['service_raw']??'');$cash=$s['cash_due_cents']??null;if($cash!==null&&(int)$cash<0)return null;if($service==='STANDARD')return $cash===null||(int)$cash===0?'NETOPIA':'FAN';return $service==='CONT COLECTOR'&&(int)$cash>0?'FAN':null;}
function decision(\PDO $db,string $action,array $targets,array $proof,string $reason,?array $actor,string $key,?int $difference=null,?string $legacy=null):int{query($db,'INSERT INTO decisions(idempotency_key,action,invoice_id,order_id,shipment_id,payment_id,source_hashes_json,reason,accepted_difference_cents,actor_id,legacy_actor,legacy_reference,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,UTC_TIMESTAMP())',[$key,$action,$targets['invoice']??null,$targets['order']??null,$targets['shipment']??null,$targets['payment']??null,json($proof),$reason,$difference,$actor['id']??null,$actor['legacy_actor']??null,$legacy]);return (int)$db->lastInsertId();}
function bootstrap():void{ini_set('display_errors','0');date_default_timezone_set('Europe/Bucharest');if(PHP_SAPI!=='cli'){$maintenance=storage().'/deployment-maintenance.json';if(is_file($maintenance)){$rule=json_decode((string)file_get_contents($maintenance),true);if(!isset($rule['token_sha'])||!hash_equals($rule['token_sha'],hash('sha256',$_SERVER['HTTP_X_DEPLOY_TOKEN']??''))){http_response_code(503);header('Retry-After: 30');exit('Actualizare în curs. Reîncearcă în câteva momente.');}}if(configured()&&(config()['require_https']??false)&&!https()){http_response_code(503);exit('Aplicația necesită HTTPS. Verifică profilul Web Station.');}session_name(preview()?'plati_rebuild':'plati_'.substr(hash('sha256',storage()),0,12));session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off']);session_start();$_SESSION['csrf']??=bin2hex(random_bytes(24));header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'");header('Referrer-Policy: same-origin');header('Cache-Control: no-store');}}
